package org.apache.commons.lang.time;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.TimeZone;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for DurationFormatUtils.formatDuration
 * Designed to maximize branch and line coverage.
 */
public class DurationFormatUtils_formatDuration_TriageGen0Test {

    @Test
    public void testFormatDuration_AllTokens_WithPadding() {
        // 1 day, 2 hours, 3 minutes, 4 seconds, 567 millis
        long duration = (1L * 24 * 60 * 60 * 1000) + (2L * 60 * 60 * 1000) + (3L * 60 * 1000) + (4L * 1000) + 567L;
        String format = "d' days 'H' hours 'm' minutes 's' seconds 'S' millis";
        String result = DurationFormatUtils.formatDuration(duration, format, true);
        // Note: Exact string depends on internal 'format' implementation, 
        // but assuming standard behavior for the tokens.
        assertEquals("1 days 02 hours 03 minutes 04 seconds 567 millis", result);
    }

    @Test
    public void testFormatDuration_AllTokens_NoPadding() {
        long duration = (1L * 24 * 60 * 60 * 1000) + (2L * 60 * 60 * 1000) + (3L * 60 * 1000) + (4L * 1000) + 567L;
        String format = "d'd'H'h'm'm's's'S'ms";
        String result = DurationFormatUtils.formatDuration(duration, format, false);
        assertEquals("1d2h3m4s567ms", result);
    }

    @Test
    public void testFormatDuration_OnlyHoursAndMinutes() {
        // 2 hours, 30 minutes
        long duration = (2L * 60 * 60 * 1000) + (30L * 60 * 1000);
        String format = "H:mm";
        String result = DurationFormatUtils.formatDuration(duration, format, true);
        assertEquals("02:30", result);
    }

    @Test
    public void testFormatDuration_OnlySeconds() {
        // 45 seconds
        long duration = 45000L;
        String format = "ss";
        String result = DurationFormatUtils.formatDuration(duration, format, true);
        assertEquals("45", result);
    }

    @Test
    public void testFormatDuration_OnlyMilliseconds() {
        // 500 milliseconds
        long duration = 500L;
        String format = "SSS";
        String result = DurationFormatUtils.formatDuration(duration, format, true);
        assertEquals("500", result);
    }

    @Test
    public void testFormatDuration_DaysOnly() {
        // 5 days
        long duration = 5L * 24 * 60 * 60 * 1000;
        String format = "d";
        String result = DurationFormatUtils.formatDuration(duration, format, false);
        assertEquals("5", result);
    }

    @Test
    public void testFormatDuration_ZeroDuration() {
        long duration = 0L;
        String format = "H:mm:ss";
        String result = DurationFormatUtils.formatDuration(duration, format, true);
        assertEquals("00:00:00", result);
    }

    @Test
    public void testFormatDuration_LargeDuration_NoDaysInFormat() {
        // 25 hours (1 day, 1 hour) but format only asks for hours
        long duration = (25L * 60 * 60 * 1000);
        String format = "H";
        String result = DurationFormatUtils.formatDuration(duration, format, false);
        // Since 'd' is not in token, it calculates days but doesn't use them. 
        // The remaining duration for hours calculation is processed.
        // Based on the logic: if (contains d) { days = ...; durationMillis = durationMillis - days... }
        // So 25 hours becomes 1 hour in the 'hours' variable.
        assertEquals("1", result);
    }

    @Test
    public void testFormatDuration_MixedTokens_Subset() {
        // 1 hour, 5 seconds
        long duration = (1L * 60 * 60 * 1000) + (5L * 1000);
        String format = "H'h 's's'";
        String result = DurationFormatUtils.formatDuration(duration, format, false);
        assertEquals("1h 5s", result);
    }

    @Test
    public void testFormatDuration_NoTokens() {
        // Just a literal string
        long duration = 1000L;
        String format = "'Hello World'";
        String result = DurationFormatUtils.formatDuration(duration, format, false);
        assertEquals("Hello World", result);
    }
}
